-- ============================================================================
-- PGifts Direct clothing: finished sell price from Dave's spreadsheet Totals.
-- Adds total_sell_price and seeds it from the "... off Total" columns (garment +
-- print + profit, verbatim). The old build summed garment+print (omitting profit)
-- and had NO white rows for hoodie/sweat/polo (white fell back to an unrelated
-- tier -> white showed dearer than coloured). Both fixed here. Laltex untouched.
-- APPLY (CLAUDE.md §52): Supabase SQL Editor, paste, Run. No BEGIN/COMMIT.
-- Idempotent. Final SELECT must return 8 rows (4 garments x 2 variants counts).
-- ============================================================================

ALTER TABLE public.catalog_print_pricing ADD COLUMN IF NOT EXISTS total_sell_price numeric(10,2);
COMMENT ON COLUMN public.catalog_print_pricing.total_sell_price IS 'PGifts Direct clothing finished per-unit sell price (garment+print+profit) taken verbatim from Dave''s spreadsheet Total columns. Read as-is, NO margin applied. NULL for products/rows priced by the legacy garment_cost+print_cost path (e.g. hi-vis-vest).';

